const guard=new URL(process.env.DATABASE_URL??'');assert.equal(guard.hostname,'test-db');assert.equal(guard.pathname,'/samvev_test');
const keyDir=resolve(process.cwd(),'.local/m23-api-test');const keyFile=resolve(keyDir,'master-key');
let app:FastifyInstance;let ai:AiAdminService;let aiCalls=0;let extractionEvents:any[]=[];let failProvider=false;let failAfterToolResult=false;let skipSourceTool=false;let fetchFailureCode:string|null=null;let interpretationRefusalSummary:string|null=null;let interpretationRefusalRemaining=0;let interpretationInvalidRemaining=0;let beforeProviderResponse:(()=>Promise<void>)|undefined;
const transport=async(_url:string,init:RequestInit)=>{aiCalls++;if(failProvider)throw new Error('synthetic failure');const body=JSON.parse(String(init.body));const responsesInput=Array.isArray(body.input)?body.input:[];const input=String(body.messages?.[0]?.content??responsesInput[0]?.content?.[0]?.text??body.input??'');const headline=input.includes('present the headline');const needsTool=input.includes('MUST use it before returning source facts');const hasToolResult=body.messages?.some((message:any)=>message.role==='tool')||responsesInput.some((item:any)=>item.type==='function_call_output');const toolRequired=body.tool_choice==='required';const approvedRoot=input.match(/approved root(?: URL| source) is (https?:\/\/\S+)\. (?:Use|You)/i)?.[1]??source.finalUrl;if(needsTool){assert.equal(body.max_output_tokens??body.max_tokens,headline?300:4096);assert.match(input,/For "first headline", use the first editorial heading in the tool's document-ordered headings/);assert.match(input,/evidence\.sourceUrl may be omitted because Samvev anchors the quote to actual tool history/);}if(body.tools)assert.ok(['auto','required'].includes(body.tool_choice));if(failAfterToolResult&&hasToolResult)throw new Error('synthetic failure after a successful tool');if((needsTool||toolRequired)&&!hasToolResult&&!skipSourceTool){const wireName=body.messages?body.tools?.[0]?.function?.name:body.tools?.[0]?.name;assert.match(wireName,/^[A-Za-z0-9_-]{1,64}$/);if(body.messages)return new Response(JSON.stringify({choices:[{message:{role:'assistant',content:'Opening the approved source.',tool_calls:[{id:'call_source',type:'function',function:{name:wireName,arguments:JSON.stringify({url:approvedRoot})}}]}}],usage:{prompt_tokens:7,completion_tokens:3}}),{status:200});return new Response(JSON.stringify({status:'completed',output:[{type:'message',content:[{type:'output_text',text:'Opening the approved source.'}]},{type:'function_call',id:'fc_source',call_id:'call_source',name:wireName,arguments:JSON.stringify({url:approvedRoot})}],usage:{input_tokens:7,output_tokens:3}}),{status:200});}const refusal=interpretationRefusalRemaining>0?(interpretationRefusalRemaining--,interpretationRefusalSummary):null;const invalidInterpretation=interpretationInvalidRemaining>0?(interpretationInvalidRemaining--,true):false;const output=invalidInterpretation?'not strict JSON':input.includes('configure a durable Samvev task')?JSON.stringify({version:1,resultKind:headline?'answer':'events',summary:refusal??(headline?'Read the current headline from the approved source.':'Find future trip days and notify the selected display the evening before.'),eventTypes:headline?[]:['trip day'],keywords:headline?[]:['trip'],people:headline?[]:['A'],noticeDaysBefore:1,noticeLocalTime:'18:00',checkIntervalMinutes:60}):headline?JSON.stringify({version:1,answer:skipSourceTool?'I cannot access the website':'Synthetic headline',evidence:{quote:skipSourceTool?'I cannot access the website':'Synthetic headline',sourceUrl:approvedRoot},confidence:0.99,uncertainty:null}):JSON.stringify({version:1,events:extractionEvents});if(beforeProviderResponse){const callback=beforeProviderResponse;beforeProviderResponse=undefined;await callback();}if(body.messages)return new Response(JSON.stringify({choices:[{message:{content:output}}],usage:{prompt_tokens:12,completion_tokens:8}}),{status:200});return new Response(JSON.stringify({status:'completed',output:[{type:'message',content:[{type:'output_text',text:output}]}],usage:{input_tokens:12,output_tokens:8}}),{status:200});};
let source:SourceDocument={finalUrl:'https://example.com/plan',contentType:'text/html',text:'Trip day 2030-09-20 for A. Bring a backpack.',fingerprint:'fingerprint-one'};
const fetcher={fetch:async()=>{if(fetchFailureCode)throw new DomainError(fetchFailureCode as any,fetchFailureCode==='MONITOR_SOURCE_TIMEOUT'?504:422);return source;}} as unknown as MonitorSourceFetcher;
function auth(token:string,csrf:string){return {cookie:`samvev_session=${token}`,'x-csrf-token':csrf};}

